static inline void token_Json_describe_(dagr_describer *d, token_Arena *a, const token_JsonValue *v) {
  (void)a;
  if (v == NULL || v->tag >= 6) {
    dagr_desc_none(d);
    return;
  }
  switch (v->tag) {
    case 0: {
      dagr_desc_raw(d, "string(");
      dagr_desc_str(d, v->as.string);
      dagr_desc_raw(d, ")");
      break;
    }
    case 1: {
      dagr_desc_raw(d, "number(");
      dagr_desc_f64(d, v->as.number);
      dagr_desc_raw(d, ")");
      break;
    }
    case 2: {
      dagr_desc_raw(d, "bool(");
      dagr_desc_bool(d, v->as.bool_);
      dagr_desc_raw(d, ")");
      break;
    }
    case 3: {
      dagr_desc_raw(d, "array(");
      dagr_desc_raw(d, "[");
      for (size_t i = 0; i < v->as.array.len; i++) {
        dagr_desc_sep(d, i);
        if (!dagr_is_present(v->as.array.present, i)) {
          dagr_desc_none(d);
          continue;
        }
        token_Json_describe_(d, a, &v->as.array.ptr[i]);
      }
      dagr_desc_raw(d, "]");
      dagr_desc_raw(d, ")");
      break;
    }
    case 4: {
      dagr_desc_raw(d, "object(");
      dagr_desc_raw(d, "[");
      for (size_t i = 0; i < v->as.object.len; i++) {
        dagr_desc_sep(d, i);
        token_JsonMember_describe_(d, a, v->as.object.ptr[i]);
      }
      dagr_desc_raw(d, "]");
      dagr_desc_raw(d, ")");
      break;
    }
    case 5: {
      dagr_desc_raw(d, "data(");
      dagr_desc_bytes(d, v->as.data);
      dagr_desc_raw(d, ")");
      break;
    }
    default:
      dagr_desc_none(d);
  }
}

static inline void token_Claims_describe_(dagr_describer *d, token_Arena *a, uint64_t id) {
  token_ClaimsRecord *r = token_Claims_at_(a, id);
  if (r == NULL || !token_Claims_live_(a, id)) {
    dagr_desc_none(d);
    return;
  }
  if (!dagr_desc_enter(d, 0, "Claims", id)) return;
  dagr_desc_field(d, "subject", true);
  if (!r->has_subject) {
    dagr_desc_none(d);
  } else {
    dagr_desc_str(d, r->subject);
  }
  dagr_desc_field(d, "issuer", false);
  if (!r->has_issuer) {
    dagr_desc_none(d);
  } else {
    dagr_desc_str(d, r->issuer);
  }
  dagr_desc_field(d, "audience", false);
  if (!r->has_audience) {
    dagr_desc_none(d);
  } else {
    dagr_desc_str(d, r->audience);
  }
  dagr_desc_field(d, "issuedAt", false);
  dagr_desc_u64(d, (uint64_t)r->issued_at);
  dagr_desc_field(d, "expiresAt", false);
  dagr_desc_u64(d, (uint64_t)r->expires_at);
  dagr_desc_field(d, "scopes", false);
  if (!r->has_scopes) {
    dagr_desc_none(d);
  } else {
    dagr_desc_raw(d, "[");
    for (size_t i = 0; i < r->scopes.len; i++) {
      dagr_desc_sep(d, i);
      dagr_desc_str(d, r->scopes.ptr[i]);
    }
    dagr_desc_raw(d, "]");
  }
  dagr_desc_field(d, "custom", false);
  if (r->custom.tag == 0xffffffffu) {
    dagr_desc_none(d);
  } else {
    token_Json_describe_(d, a, &r->custom);
  }
  dagr_desc_leave(d);
}

static inline dagr_describer token_Claims_describe_all_(token_ClaimsHandle h) {
  dagr_describer d = dagr_describer_init(h.arena != NULL ? h.arena->alloc : dagr_default_allocator(), dagr_default_max_depth);
  if (h.arena == NULL) dagr_desc_none(&d);
  else token_Claims_describe_(&d, h.arena, h.id);
  return d;
}

/** The node and everything it reaches, as text — a node met again is `Name#n`, floats are their bits — into `buf` (NUL-terminated, cut at `cap - 1`); returns the full length, as snprintf does (0 when an allocation failed). */
static inline size_t token_ClaimsHandle_to_string(token_ClaimsHandle h, char *buf, size_t cap) {
  dagr_describer d = token_Claims_describe_all_(h);
  return dagr_describer_take(&d, buf, cap);
}

/** Structural equality, across arenas: the same values and the same shape of references — sharing and cycles included — whatever the ids. */
static inline bool token_ClaimsHandle_equals(token_ClaimsHandle x, token_ClaimsHandle y) {
  dagr_describer dx = token_Claims_describe_all_(x);
  dagr_describer dy = token_Claims_describe_all_(y);
  return dagr_describer_same(&dx, &dy);
}

/** A hash of what `_equals` compares: equal nodes hash alike. */
static inline uint64_t token_ClaimsHandle_hash(token_ClaimsHandle h) {
  dagr_describer d = token_Claims_describe_all_(h);
  return dagr_describer_hash(&d);
}

static inline void token_JsonMember_describe_(dagr_describer *d, token_Arena *a, uint64_t id) {
  token_JsonMemberRecord *r = token_JsonMember_at_(a, id);
  if (r == NULL || !token_JsonMember_live_(a, id)) {
    dagr_desc_none(d);
    return;
  }
  if (!dagr_desc_enter(d, 1, "JsonMember", id)) return;
  dagr_desc_field(d, "key", true);
  dagr_desc_str(d, r->key);
  dagr_desc_field(d, "value", false);
  if (r->value.tag == 0xffffffffu) {
    dagr_desc_none(d);
  } else {
    token_Json_describe_(d, a, &r->value);
  }
  dagr_desc_leave(d);
}

