/** An empty arena growing through `alloc` (`dagr_default_allocator()`: malloc). */
static inline void token_Arena_init(token_Arena *a, dagr_allocator alloc) {
  memset(a, 0, sizeof *a);
  a->alloc = alloc;
  a->status = dagr_ok;
  a->root = dagr_no_handle;
}

/** Frees every node and what it holds; the arena is empty (and reusable) afterwards. */
static inline void token_Arena_free(token_Arena *a) {
  for (size_t i = 0; i < a->claims_store_len; i++) token_Claims_drop_(a, a->claims_store + i);
  dagr_release(&a->alloc, a->claims_store);
  for (size_t i = 0; i < a->json_member_store_len; i++) token_JsonMember_drop_(a, a->json_member_store + i);
  dagr_release(&a->alloc, a->json_member_store);
  token_Arena_init(a, a->alloc);
}

/** `dagr_out_of_memory` once an allocation has failed (sticky); `dagr_ok` otherwise. */
static inline dagr_status token_Arena_status(const token_Arena *a) {
  return a->status;
}

/** The root (the empty handle when none is set, or it is gone). */
static inline token_ClaimsHandle token_Arena_root(token_Arena *a) {
  return token_Claims_live_(a, a->root) ? token_Claims_handle_(a, a->root) : token_Claims_handle_(NULL, dagr_no_handle);
}

static inline void token_Arena_set_root(token_Arena *a, token_ClaimsHandle root) {
  if (root.arena != a || token_Claims_rec_(root) == NULL) dagr_arena_misuse("a root of another arena, or an empty one");
  a->root = root.id;
}

/** Replaces the arena's contents with the graph in `buf` (a `Token` buffer): every node, shared and cyclic ones once. Fails with `dagr_bad_framing`, `dagr_depth_exceeded` (nested deeper than `max_depth` — `dagr_default_max_depth`) or `dagr_out_of_memory`; the strings and arrays are copied, so `buf` may go away. */
static inline dagr_status token_Arena_restore(token_Arena *a, dagr_bytes buf, size_t max_depth) {
  token_Arena_free(a);
  token_ClaimsAccessor acc;
  const dagr_status opened = token_open(buf, &acc);
  if (opened != dagr_ok) return opened;
  dagr_restore_seen s = dagr_restore_seen_init(max_depth, a->alloc);
  const uint64_t root = token_Claims_restore_own_(a, &s, &acc);
  token_restore_drain_(a, &s);   /* the nodes reached by reference (spec/49 R1) */
  const dagr_status out = s.status != dagr_ok ? s.status : a->status;
  dagr_restore_seen_free(&s);
  if (out == dagr_ok) a->root = root;
  return out;
}

/** The arena's graph as a `Token` buffer — byte-identical to every other Dagr writer — into `b` (reset first) with the caches `c` (reset first; their `max_size` fixes the cycle placeholder width). Empty when it failed; `b->status` says why (`dagr_invalid_value`: a required reference never set, a union value with no variant, or no root). The buffer carries NO spec-15 header: `token_Arena_serialize_with_header` writes one. */
static inline dagr_bytes token_Arena_serialize(token_Arena *a, dagr_builder *b, dagr_graph_caches *c) {
  dagr_builder_reset(b);
  dagr_graph_caches_reset(c);
  if (a->status != dagr_ok) {
    dagr_builder_fail(b, a->status);
    return dagr_bytes_of(NULL, 0);
  }
  if (a->root == dagr_no_handle) {
    dagr_builder_fail(b, dagr_invalid_value);
    return dagr_bytes_of(NULL, 0);
  }
  dagr_graph_writer w = dagr_graph_writer_of(b, c);
  const dagr_node_ref root = token_Claims_store_(&w, a, a->root);
  dagr_store_graph_framing_at(b, root.off, 1);
  return dagr_builder_bytes(b);
}

/** Stores one `Jws` — its packed block, children included — below what `b` holds. */
static inline void token_Jws_put(dagr_builder *b, const token_Jws *n) {
  const size_t before = b->cursor;
  dagr_store_packed_blob_field(b, n->signature.ptr, n->signature.len, 2);
  if (n->has_key_id) {
    dagr_store_packed_blob_field(b, n->key_id.ptr, n->key_id.len, 1);
  }
  dagr_store_packed_blob_field(b, n->algorithm.ptr, n->algorithm.len, 0);
  dagr_store_leb(b, b->cursor - before);
}

/** `[Jws]` (`present` NULL) or `[Jws?]`: `[count][nil bitset?][blocks]`. */
static inline void token_Jws_put_array(dagr_builder *b, const token_Jws *elems, const bool *present, size_t count) {
  const size_t before = b->cursor;
  for (size_t i = count; i-- > 0;) {
    if (dagr_is_present(present, i)) token_Jws_put(b, elems + i);
  }
  if (present != NULL) dagr_store_nil_bits(b, present, count);
  dagr_pk_finish_block(b, before, count);
}

/** One `Jws` and everything under it as plain values: strings and data stay views of the
 * buffer, arrays (and nodes held by pointer) go to the context's scratch memory. */
static inline token_Jws token_Jws_restore(dagr_restore *ctx, const token_JwsAccessor *a) {
  token_Jws out;
  memset(&out, 0, sizeof out);
  if (!dagr_restore_enter(ctx)) return out;
  out.algorithm = dagr_restore_text(ctx, token_JwsAccessor_algorithm(a));
  out.has_key_id = token_JwsAccessor_has_key_id(a);
  if (out.has_key_id) {
    out.key_id = dagr_restore_text(ctx, token_JwsAccessor_key_id(a));
  }
  out.signature = token_JwsAccessor_signature(a);
  dagr_restore_leave(ctx);
  return out;
}

/** `token_Arena_serialize` with the graph's spec-15 header in front: the body is written first, then `header_fn(context, root_offset, body, &values)` — the header-free root offset and the body's bytes, valid during the call only — gives the header's values, which are stored packed before the body. With aligned arrays the header is inflated so the buffer stays a multiple of their alignment (spec 15 §6). */
static inline dagr_bytes token_Arena_serialize_with_header(token_Arena *a, dagr_builder *b, dagr_graph_caches *c, token_HeaderFn header_fn, void *context) {
  dagr_builder_reset(b);
  dagr_graph_caches_reset(c);
  if (a->status != dagr_ok) {
    dagr_builder_fail(b, a->status);
    return dagr_bytes_of(NULL, 0);
  }
  if (a->root == dagr_no_handle) {
    dagr_builder_fail(b, dagr_invalid_value);
    return dagr_bytes_of(NULL, 0);
  }
  dagr_graph_writer w = dagr_graph_writer_of(b, c);
  const dagr_node_ref root = token_Claims_store_(&w, a, a->root);
  if (b->status != dagr_ok) return dagr_bytes_of(NULL, 0);
  const size_t body = b->cursor;
  const size_t root_offset = b->cursor - root.off;
  token_Jws values;
  memset(&values, 0, sizeof values);
  header_fn(context, root_offset, dagr_builder_bytes(b), &values);
  const size_t q = 0;
  token_Jws_put(b, &values);
  dagr_store_header_frame(b, body, q, root_offset);
  return dagr_builder_bytes(b);
}

static inline uint64_t token_Claims_restore_own_(token_Arena *a, dagr_restore_seen *s, const token_ClaimsAccessor *acc) {
  if (acc->pos == SIZE_MAX || s->status != dagr_ok) return dagr_no_handle;
  const uint64_t seen = dagr_seen_find(s, 0, acc->pos);
  if (seen != dagr_no_handle) return seen;
  if (!dagr_seen_enter(s)) return dagr_no_handle;
  const token_ClaimsHandle h = token_Claims_alloc_(a, false);
  if (h.arena == NULL) {
    dagr_seen_fail(s, dagr_out_of_memory);
    dagr_seen_leave(s);
    return dagr_no_handle;
  }
  dagr_seen_add(s, 0, acc->pos, h.id);
  bool ok = true;
  if (token_ClaimsAccessor_has_subject(acc)) {
    const dagr_str v = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, token_ClaimsAccessor_subject(acc)), &ok);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->subject = v;
    if (r != NULL) r->has_subject = true;
  }
  if (token_ClaimsAccessor_has_issuer(acc)) {
    const dagr_str v = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, token_ClaimsAccessor_issuer(acc)), &ok);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->issuer = v;
    if (r != NULL) r->has_issuer = true;
  }
  if (token_ClaimsAccessor_has_audience(acc)) {
    const dagr_str v = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, token_ClaimsAccessor_audience(acc)), &ok);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->audience = v;
    if (r != NULL) r->has_audience = true;
  }
  {
    const uint64_t v = token_ClaimsAccessor_issued_at(acc);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->issued_at = v;
  }
  {
    const uint64_t v = token_ClaimsAccessor_expires_at(acc);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->expires_at = v;
  }
  if (token_ClaimsAccessor_has_scopes(acc)) {
    dagr_str_opt_slice v;
    memset(&v, 0, sizeof v);
    {
      dagr_pk_array it = token_ClaimsAccessor_scopes(acc);
      const size_t n = it.count;
      dagr_str *elems = dagr_arena_zeroed(&a->alloc, n, sizeof(dagr_str), &ok);
      size_t k = 0;
      size_t e;
      while (elems != NULL && k < n && dagr_pk_next_blob(&it, &e, NULL)) {
        elems[k] = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, dagr_read_text(it.buf, e)), &ok);
        k++;
      }
      v.ptr = elems;
      v.present = NULL;
      v.len = k;
    }
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->scopes = v;
    if (r != NULL) r->has_scopes = true;
  }
  if (token_ClaimsAccessor_has_custom(acc)) {
    const token_JsonValue v = token_Json_restore_packed_(a, s, token_ClaimsAccessor_custom(acc), &ok);
    token_ClaimsRecord *r = token_Claims_rec_(h);
    if (r != NULL) r->custom = v;
  }
  if (!ok) {
    a->status = dagr_out_of_memory;
    dagr_seen_fail(s, dagr_out_of_memory);
  }
  dagr_seen_leave(s);
  return h.id;
}

static inline dagr_node_ref token_Claims_store_(dagr_graph_writer *w, token_Arena *a, uint64_t id) {
  if (token_Claims_at_(a, id) == NULL) {
    dagr_builder_fail(w->b, dagr_invalid_value);
    return dagr_node_ref_at(w->b->cursor);
  }
  size_t off = 0;
  if (dagr_gw_cached(w, 0, id, &off)) return dagr_node_ref_at(off);
  return dagr_node_ref_at(token_Claims_put_packed_(w, a, id));
}

static inline token_JsonValue token_Json_restore_packed_(token_Arena *a, dagr_restore_seen *s, token_JsonPackedView v, bool *ok) {
  (void)a;
  (void)ok;
  token_JsonValue out = token_JsonValue_none();
  if (!token_JsonPackedView_has_variant(v)) return out;
  if (!dagr_seen_enter(s)) return out;
  switch (token_JsonPackedView_tag(v)) {
    case 0: {
      const dagr_str x = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, token_JsonPackedView_string(v)), ok);
      out.as.string = x;
      out.tag = 0;
      break;
    }
    case 1: {
      const double x = token_JsonPackedView_number(v);
      out.as.number = x;
      out.tag = 1;
      break;
    }
    case 2: {
      const bool x = token_JsonPackedView_bool(v);
      out.as.bool_ = x;
      out.tag = 2;
      break;
    }
    case 3: {
      token_JsonValueArray x;
      memset(&x, 0, sizeof x);
      {
        dagr_pk_array it = token_JsonPackedView_array(v);
        const size_t n = it.count;
        token_JsonValue *elems = dagr_arena_zeroed(&a->alloc, n, sizeof(token_JsonValue), ok);
        bool *pres = dagr_arena_zeroed(&a->alloc, n, sizeof(bool), ok);
        bool present = true;
        size_t k = 0;
        dagr_pk_union_header e;
        while (elems != NULL && pres != NULL && k < n && dagr_pk_next_union(&it, &e, &present)) {
          pres[k] = present;
          if (!present) {
            elems[k] = token_JsonValue_none();
            k++;
            continue;
          }
          elems[k] = token_Json_restore_packed_(a, s, token_JsonPackedView_of(it.buf, e), ok);
          k++;
        }
        x.ptr = elems;
        x.present = pres;
        x.len = k;
      }
      out.as.array = x;
      out.tag = 3;
      break;
    }
    case 4: {
      dagr_u64_opt_slice x;
      memset(&x, 0, sizeof x);
      {
        dagr_pk_array it = token_JsonPackedView_object(v);
        const size_t n = it.count;
        uint64_t *elems = dagr_arena_zeroed(&a->alloc, n, sizeof(uint64_t), ok);
        size_t k = 0;
        size_t e;
        while (elems != NULL && k < n && dagr_pk_next_blob(&it, &e, NULL)) {
          const token_JsonMemberAccessor c = token_JsonMemberAccessor_at(it.buf, e);
          elems[k] = token_JsonMember_restore_own_(a, s, &c);
          k++;
        }
        x.ptr = elems;
        x.present = NULL;
        x.len = k;
      }
      out.as.object = x;
      out.tag = 4;
      break;
    }
    case 5: {
      const dagr_bytes x = dagr_arena_dup_bytes(&a->alloc, token_JsonPackedView_data(v), ok);
      out.as.data = x;
      out.tag = 5;
      break;
    }
    default: break;
  }
  dagr_seen_leave(s);
  return out;
}

static inline size_t token_Claims_put_packed_(dagr_graph_writer *w, token_Arena *a, uint64_t id) {
  (void)a;
  token_ClaimsRecord *r = token_Claims_at_(a, id);
  if (r == NULL) {
    dagr_builder_fail(w->b, dagr_invalid_value);
    return w->b->cursor;
  }
  dagr_builder *b = w->b;
  (void)b;
  const size_t before = w->b->cursor;
  uint8_t encoding[1];
  memset(encoding, 0, sizeof encoding);
  uint8_t presence[1];
  memset(presence, 0, sizeof presence);
  if (r->custom.tag != 0xffffffffu) {
    dagr_set_bit(presence, 4);
    dagr_store_leb(w->b, token_Json_put_packed_payload_(w, a, &r->custom));
  }
  if (r->has_scopes) {
    dagr_set_bit(presence, 3);
    dagr_store_pk_text_array(b, r->scopes.ptr, NULL, r->scopes.len);
  }
  if (dagr_store_packed_int(b, (uint64_t)r->expires_at, 8, false, false)) dagr_set_bit(encoding, 1);
  if (dagr_store_packed_int(b, (uint64_t)r->issued_at, 8, false, false)) dagr_set_bit(encoding, 0);
  if (r->has_audience) {
    dagr_set_bit(presence, 2);
    dagr_store_text(b, r->audience);
  }
  if (r->has_issuer) {
    dagr_set_bit(presence, 1);
    dagr_store_text(b, r->issuer);
  }
  if (r->has_subject) {
    dagr_set_bit(presence, 0);
    dagr_store_text(b, r->subject);
  }
  dagr_store_bytes(w->b, encoding, sizeof encoding);
  dagr_store_bytes(w->b, presence, sizeof presence);
  dagr_store_leb(w->b, (uint64_t)(w->b->cursor - before));
  const size_t o = w->b->cursor;
  dagr_gw_cache(w, 0, id, o);
  return o;
}

static inline uint64_t token_JsonMember_restore_own_(token_Arena *a, dagr_restore_seen *s, const token_JsonMemberAccessor *acc) {
  if (acc->pos == SIZE_MAX || s->status != dagr_ok) return dagr_no_handle;
  const uint64_t seen = dagr_seen_find(s, 1, acc->pos);
  if (seen != dagr_no_handle) return seen;
  if (!dagr_seen_enter(s)) return dagr_no_handle;
  const token_JsonMemberHandle h = token_JsonMember_alloc_(a, false);
  if (h.arena == NULL) {
    dagr_seen_fail(s, dagr_out_of_memory);
    dagr_seen_leave(s);
    return dagr_no_handle;
  }
  dagr_seen_add(s, 1, acc->pos, h.id);
  bool ok = true;
  {
    const dagr_str v = dagr_arena_dup_str(&a->alloc, dagr_seen_text(s, token_JsonMemberAccessor_key(acc)), &ok);
    token_JsonMemberRecord *r = token_JsonMember_rec_(h);
    if (r != NULL) r->key = v;
  }
  if (token_JsonMemberAccessor_has_value(acc)) {
    const token_JsonValue v = token_Json_restore_packed_(a, s, token_JsonMemberAccessor_value(acc), &ok);
    token_JsonMemberRecord *r = token_JsonMember_rec_(h);
    if (r != NULL) r->value = v;
  }
  if (!ok) {
    a->status = dagr_out_of_memory;
    dagr_seen_fail(s, dagr_out_of_memory);
  }
  dagr_seen_leave(s);
  return h.id;
}

static inline uint64_t token_Json_put_packed_payload_(dagr_graph_writer *w, token_Arena *a, const token_JsonValue *v) {
  (void)a;
  if (v == NULL || v->tag >= 6) {
    dagr_builder_fail(w->b, dagr_invalid_value); /* a value that holds no variant */
    return 0;
  }
  dagr_builder *b = w->b;
  (void)b;
  switch (v->tag) {
    case 0: {
      dagr_store_text(b, v->as.string);
      return ((uint64_t)0 << 3) | 6;
    }
    case 1: {
      return ((uint64_t)1 << 3) | dagr_store_packed_union_f64(b, v->as.number);
    }
    case 2: {
      dagr_store_u8(b, v->as.bool_ ? 1 : 0);
      return ((uint64_t)2 << 3) | 1;
    }
    case 3: {
      {
        const size_t arr_before = w->b->cursor;
        const size_t base = dagr_gw_tmp_push(w, v->as.array.len, sizeof(dagr_union_elem));
        for (size_t i = v->as.array.len; i-- > 0;) {
          if (!dagr_is_present(v->as.array.present, i)) continue;
          dagr_union_elem e;
          memset(&e, 0, sizeof e);
          e.present = true;
          e.id = token_Json_put_packed_payload_(w, a, v->as.array.ptr + i);
          dagr_gw_tmp_set_elem(w, base, i, e);
        }
        dagr_gw_store_packed_union_headers(w, base, v->as.array.len, true, arr_before);
        dagr_gw_tmp_pop(w, base);
      }
      return ((uint64_t)3 << 3) | 6;
    }
    case 4: {
      {
        const size_t arr_before = w->b->cursor;
        for (size_t i = v->as.object.len; i-- > 0;) {
          if (!dagr_is_present(NULL, i)) continue;
          if (v->as.object.ptr[i] == dagr_no_handle) dagr_builder_fail(w->b, dagr_invalid_value);
          else (void)token_JsonMember_put_packed_(w, a, v->as.object.ptr[i]);
        }
        if (NULL != NULL) dagr_store_nil_bits(w->b, NULL, v->as.object.len);
        dagr_pk_finish_block(w->b, arr_before, v->as.object.len);
      }
      return ((uint64_t)4 << 3) | 6;
    }
    case 5: {
      dagr_store_data(b, v->as.data);
      return ((uint64_t)5 << 3) | 6;
    }
    default: break;
  }
  dagr_builder_fail(w->b, dagr_invalid_value);
  return 0;
}

static inline size_t token_JsonMember_put_packed_(dagr_graph_writer *w, token_Arena *a, uint64_t id) {
  (void)a;
  token_JsonMemberRecord *r = token_JsonMember_at_(a, id);
  if (r == NULL) {
    dagr_builder_fail(w->b, dagr_invalid_value);
    return w->b->cursor;
  }
  dagr_builder *b = w->b;
  (void)b;
  const size_t before = w->b->cursor;
  uint8_t presence[1];
  memset(presence, 0, sizeof presence);
  if (r->value.tag != 0xffffffffu) {
    dagr_set_bit(presence, 0);
    dagr_store_leb(w->b, token_Json_put_packed_payload_(w, a, &r->value));
  }
  dagr_store_text(b, r->key);
  dagr_store_bytes(w->b, presence, sizeof presence);
  dagr_store_leb(w->b, (uint64_t)(w->b->cursor - before));
  const size_t o = w->b->cursor;
  dagr_gw_cache(w, 1, id, o);
  return o;
}

static inline void token_restore_drain_(token_Arena *a, dagr_restore_seen *s) {
  (void)a;
  dagr_seen_pending p;
  while (dagr_seen_next(s, &p)) {
    const size_t saved = dagr_seen_restart(s);
    switch (p.type) {
      default:
        break;
    }
    dagr_seen_resume(s, saved);
  }
}

#endif /* DAGR_GEN_TOKEN_ARENA_H */
